entries[109200] = { ["name"] = "Schwindendes Licht", ["text"] = "Sofort\nEntzieht einem Ziel das Licht und zieht es ins Zwielicht. Bei seinem Erlöschen werden Ziele, die sich im Zwielichtreich befinden, sofort getötet. Ziele in der normalen Welt werden in das Zwielichtreich gezogen und jegliche gegen Ultraxion erzeugte Bedrohung wird zurückgesetzt. Zusätzlich wird 5 Sek. lang keine Bedrohung erzeugt." }
entries[109206] = { ["name"] = "Tiger & Schimäre", ["text"] = "Wenn Ihr einen Nahkampftreffer erleidet, wird die Abklingzeit Eurer Fähigkeit 'Rückzug' sofort um 4 Sek. verringert.\n\nWenn Ihr einen Distanz- oder Zaubertreffer erleidet, wird die Abklingzeit Eurer Fähigkeit 'Abschreckung' sofort um 8 Sek. verringert.\n\nDiese Effekte haben eine Abklingzeit von 2 Sek.\n(2s Abklingzeit)" }
