entries[109260] = { ["name"] = "Aspekt des eisernen Falken", ["text"] = "Ersetzt Aspekt des Falken\nSofort 1 sek. Abklingzeit\nDer Jäger nimmt die Aspekte eines eisernen Falken an: Die Distanzangriffskraft wird um 35% erhöht und der erlittene Schaden um 10% verringert. Es kann immer nur jeweils ein Aspekt aktiv sein.\n\nErsetzt 'Aspekt des Falken'." }
