entries[109466] = { ["name"] = "Fluch der Entkräftung", ["text"] = "4% von Grundmana 40 Meter Reichweite\nSofort\nBindet das Ziel mit dämonischer Energie, die seinen verursachten körperlichen Schaden um 10% verringert und seine Zauberwirkzeit um 50% (10% bei Spielercharakteren) erhöht. Hält 30 Sek. lang an.\n\nWeniger effektiv bei Dungeon- und Schlachtzugsbossen.\n\nFlüche\nEs kann pro Ziel immer nur jeweils ein Fluch des Hexenmeisters aktiv sein. [ Seelenbrand: Fluch : Seelenbrand:\nEuer Zauber 'Fluch der Entkräftung' trifft alle Gegner innerhalb von 15 Metern von Eurem Ziel. ]" }
