entries[109939] = { ["name"] = "Item - Dragon Soul Legendary Daggers", ["text"] = "Eure Nahkampfangriffe haben eine Chance, 'Schatten des Zerstörers' zu gewähren. Dadurch wird Eure Beweglichkeit um 17 erhöht. Dieser Effekt ist bis zu 50-mal stapelbar. Jede Anwendung über 30 gewährt eine erhöhte Chance, Furor des Zerstörers auszulösen. Dadurch erhaltet Ihr sofort 5 Combopunkte. Eure Finishing-Moves erzeugen dann 5 Combopunkte. Hält 6 Sek. lang an." }
