entries[109941] = { ["name"] = "Schatten des Zerstörers", ["text"] = "Sofort\nErhöht Eure Beweglichkeit um 17. Bis zu 50-mal stapelbar. Sobald Ihr 30 Stapel von 'Schatten des Zerstörers' angesammelt habt, gewährt jeder Stapel eine ansteigende Chance, 'Furor des Zerstörers' auszulösen und somit alle Stapel von 'Schatten des Zerstörers' aufzuzehren. Der Effekt 'Furor des Zerstörers' gewährt Euch sofort 5 Combopunkte und lässt Eure Finishing-Moves 5 Combopunkte erzeugen. Hält 6 Sek. lang an." }
